(()=>{'use strict';
const element=document.getElementById('stonisce-page-config');if(!element)return;
const config=JSON.parse(element.textContent),language=config.language,currentPage=config.route;
const main=document.querySelector('main[data-preview-page]'),nav=document.getElementById('siteNav'),menu=document.querySelector('.menu-toggle'),header=document.querySelector('.site-header'),scrim=document.querySelector('.v46-menu-scrim');
const labels=config.labels,reduceMotion=matchMedia('(prefers-reduced-motion: reduce)'),returnFocus=new WeakMap(),navigationClosures=new WeakSet();
let menuOpen=false,lightboxIndex=0,lightboxCards=[],inquiryRoute=currentPage,inquiryReference='',scheduled=false;
const own=(object,key)=>Object.prototype.hasOwnProperty.call(object,key);
function legacyDestination(){if(!location.hash.startsWith('#/'))return null;const bits=location.hash.slice(2).split('/').filter(Boolean);const route=own(config.urls[language],bits[0])?bits[0]:'index';let section=bits[1]||'';if(section==='collection')section='gallery-'+route;return config.urls[language][route]+(section?'#'+section:'')}
const legacy=legacyDestination();if(legacy){const target=new URL(legacy,location.origin);if(target.pathname!==location.pathname){location.replace(target.href);return}history.replaceState(history.state,'',target.pathname+target.hash)}
document.documentElement.classList.add('js');
function setMenu(open,restore=true){
 menuOpen=Boolean(open)&&innerWidth<1100;nav.classList.toggle('nav-open',menuOpen);document.body.classList.toggle('menu-open',menuOpen);menu.setAttribute('aria-expanded',String(menuOpen));menu.setAttribute('aria-label',menuOpen?labels.close:labels.open);nav.inert=innerWidth<1100&&!menuOpen;
 if(menuOpen)requestAnimationFrame(()=>nav.querySelector('a[aria-current="page"]')?.focus({preventScroll:true}));else if(restore)menu.focus({preventScroll:true});
}
function closeForNavigation(){setMenu(false,false);document.querySelectorAll('.v46-dialog[open]').forEach(dialog=>{navigationClosures.add(dialog);dialog.close()})}
function currentSection(){if(!location.hash||location.hash.startsWith('#/'))return null;let id;try{id=decodeURIComponent(location.hash.slice(1))}catch(_){return null}return document.getElementById(id)}
function scrollSection(section,{smooth=false,focus=false}={}){if(!section)return;const indexHeight=currentPage==='index'?(document.querySelector('.v46-collection-index')?.offsetHeight||0):20;const top=Math.max(0,section.getBoundingClientRect().top+window.scrollY-header.offsetHeight-indexHeight);window.scrollTo({top,behavior:smooth&&!reduceMotion.matches?'smooth':'instant'});if(focus){section.tabIndex=-1;section.focus({preventScroll:true})}}
function viewportMetrics(){document.documentElement.style.setProperty('--header-height',header.offsetHeight+'px');const height=window.visualViewport?.height||innerHeight;document.documentElement.style.setProperty('--visual-viewport-height',height+'px')}
menu.addEventListener('click',()=>setMenu(!menuOpen));scrim.addEventListener('click',()=>setMenu(false));nav.addEventListener('click',event=>{if(event.target.closest('a'))setMenu(false,false)});
window.addEventListener('resize',()=>{if(innerWidth>=1100&&menuOpen)setMenu(false,false);else nav.inert=innerWidth<1100&&!menuOpen;viewportMetrics();updateScroll()},{passive:true});window.visualViewport?.addEventListener('resize',viewportMetrics,{passive:true});
document.addEventListener('keydown',event=>{
 if(menuOpen&&event.key==='Escape'){event.preventDefault();setMenu(false)}
 if(menuOpen&&event.key==='Tab'){const focusable=[...header.querySelectorAll('a,button')].filter(el=>el.getClientRects().length&&!el.disabled);const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
 const dialog=document.getElementById('image-dialog');if(dialog.open&&(event.key==='ArrowRight'||event.key==='ArrowLeft')){event.preventDefault();lightboxIndex=(lightboxIndex+(event.key==='ArrowRight'?1:-1)+lightboxCards.length)%lightboxCards.length;renderLightbox()}
});
document.addEventListener('click',event=>{
 const a=event.target.closest('a');if(!a||event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;
 if(a.matches('[data-lightbox]')&&typeof document.getElementById('image-dialog').showModal==='function'){event.preventDefault();openLightbox(a);return}
 if(a.matches('[data-inquiry]')&&typeof document.getElementById('project-dialog').showModal==='function'){event.preventDefault();openInquiry(a.dataset.inquiry==='current'?currentPage:a.dataset.inquiry,a);return}
 if(a.matches('[data-lang]')&&location.hash&&!location.hash.startsWith('#/')){const target=new URL(a.href);target.hash=location.hash;a.href=target.pathname+target.hash}
 const url=new URL(a.href,location.href);if(url.origin!==location.origin)return;
 if(url.pathname===location.pathname&&url.hash&&!url.hash.startsWith('#/')){let id;try{id=decodeURIComponent(url.hash.slice(1))}catch(_){return}const section=document.getElementById(id);if(section){event.preventDefault();closeForNavigation();if(location.hash!==url.hash)history.pushState(null,'',url.pathname+url.search+url.hash);scrollSection(section,{smooth:true,focus:true})}}
 else closeForNavigation();
});
document.querySelector('.skip-link').addEventListener('click',event=>{event.preventDefault();const heading=main.querySelector('h1');heading.tabIndex=-1;heading.focus({preventScroll:true});scrollSection(heading,{smooth:true,focus:false})});
window.addEventListener('hashchange',()=>{const destination=legacyDestination();if(destination){location.replace(destination);return}closeForNavigation();requestAnimationFrame(()=>scrollSection(currentSection(),{focus:true}))});
window.addEventListener('popstate',()=>{closeForNavigation();if(location.hash&&!location.hash.startsWith('#/'))requestAnimationFrame(()=>scrollSection(currentSection(),{focus:true}))});
window.addEventListener('pagehide',closeForNavigation);window.addEventListener('pageshow',()=>{setMenu(false,false);document.querySelectorAll('.v46-dialog[open]').forEach(dialog=>dialog.close());document.body.classList.remove('dialog-open');viewportMetrics();updateScroll()});
function updateScroll(){const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.v46-progress').style.transform='scaleX('+(max>0?Math.max(0,Math.min(1,scrollY/max)):0)+')';header.classList.toggle('is-scrolled',scrollY>8);if(currentPage==='index'){let active='';for(const panel of main.querySelectorAll('.v42-panel'))if(panel.getBoundingClientRect().top<=innerHeight*.48)active=panel.id;document.querySelectorAll('.v46-collection-index a').forEach(a=>{const selected=a.hash==='#'+active&&active!=='';a.classList.toggle('is-active',selected);if(selected)a.setAttribute('aria-current','true');else a.removeAttribute('aria-current')})}}
window.addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(()=>{scheduled=false;updateScroll()})}},{passive:true});
if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-revealed');observer.unobserve(entry.target)}}),{threshold:.12});document.querySelectorAll('.v42-panel-inner,.project-statement .statement-grid>div,.process-grid>div,.v46-gallery-intro').forEach(el=>{el.classList.add('v46-reveal');observer.observe(el)})}
document.querySelectorAll('img[data-asset]').forEach(img=>img.addEventListener('error',()=>{img.classList.add('image-failed');const frame=img.closest('.preview-img,.v42-media,.collection-lead,.asset-frame,.feature-image');if(frame)frame.dataset.imageError=labels.imageError},{once:true}));
function imageSource(name){return'/assets/'+encodeURIComponent(name)}
function openDialog(dialog,trigger){setMenu(false,false);returnFocus.set(dialog,trigger||document.activeElement);dialog.showModal();document.body.classList.add('dialog-open');viewportMetrics()}
function closeDialog(dialog){if(dialog.open)dialog.close()}
document.querySelectorAll('.v46-dialog').forEach(dialog=>{
 dialog.addEventListener('close',()=>{if(!document.querySelector('.v46-dialog[open]'))document.body.classList.remove('dialog-open');if(navigationClosures.has(dialog)){navigationClosures.delete(dialog);return}const trigger=returnFocus.get(dialog);if(trigger?.isConnected&&trigger.getClientRects().length)trigger.focus({preventScroll:true});else{const heading=main.querySelector('h1');heading.tabIndex=-1;heading.focus({preventScroll:true})}});
 dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog(dialog)}});
 dialog.querySelectorAll('[data-close-dialog]').forEach(button=>button.addEventListener('click',()=>closeDialog(dialog)));
});
function openLightbox(card){lightboxCards=[...main.querySelectorAll('[data-lightbox]')];lightboxIndex=lightboxCards.indexOf(card);renderLightbox();openDialog(document.getElementById('image-dialog'),card)}
function renderLightbox(){const card=lightboxCards[lightboxIndex];if(!card)return;const source=card.querySelector('img'),img=document.getElementById('lightbox-image');img.src=imageSource(source.dataset.asset);img.alt=source.alt;img.width=Number(source.getAttribute('width'));img.height=Number(source.getAttribute('height'));img.style.maxWidth='100%';img.style.width='auto';img.style.height='auto';document.getElementById('lightbox-title').textContent=card.querySelector('strong')?.textContent||source.alt;document.getElementById('lightbox-description').textContent=card.querySelector('.preview-meta p')?.textContent||'';document.getElementById('lightbox-label').textContent=card.querySelector('.concept-label')?.textContent||'';document.getElementById('lightbox-count').textContent=String(lightboxIndex+1).padStart(2,'0')+' / '+String(lightboxCards.length).padStart(2,'0');document.getElementById('lightbox-inquiry').textContent=config.collections[currentPage].contactCta;img.classList.toggle('modal-crop-panels',source.dataset.asset==='h4-panels.webp')}
document.getElementById('image-prev').addEventListener('click',()=>{lightboxIndex=(lightboxIndex-1+lightboxCards.length)%lightboxCards.length;renderLightbox()});document.getElementById('image-next').addEventListener('click',()=>{lightboxIndex=(lightboxIndex+1)%lightboxCards.length;renderLightbox()});
document.getElementById('lightbox-inquiry').addEventListener('click',()=>{const reference=document.getElementById('lightbox-title').textContent;const dialog=document.getElementById('image-dialog');navigationClosures.add(dialog);closeDialog(dialog);openInquiry(currentPage,lightboxCards[lightboxIndex],reference)});
function openInquiry(route,trigger,reference=''){inquiryRoute=own(config.collections,route)?route:currentPage;inquiryReference=reference;document.getElementById('project-form').reset();updateInquiry();openDialog(document.getElementById('project-dialog'),trigger)}
function updateInquiry(){const entry=config.collections[inquiryRoute],name=entry.name||labels.generic;document.getElementById('inquiry-title').textContent=entry.contactCta;document.getElementById('inquiry-context').textContent='STONISCE / '+name;const dimensions=document.getElementById('project-dimensions').value.trim(),material=document.getElementById('project-material').value.trim(),brief=document.getElementById('project-brief').value.trim();let message=labels.hello+' '+name+'.';if(inquiryReference)message+='\n'+labels.source+': '+inquiryReference;if(dimensions)message+='\n'+labels.dimensions+': '+dimensions;if(material)message+='\n'+labels.material+': '+material;if(brief)message+='\n'+labels.brief+': '+brief;document.getElementById('project-whatsapp').href='https://wa.me/'+config.whatsappPhone+'?text='+encodeURIComponent(message)}
document.getElementById('project-form').addEventListener('input',updateInquiry);document.getElementById('project-form').addEventListener('submit',event=>event.preventDefault());
viewportMetrics();setMenu(false,false);updateScroll();if(location.hash)requestAnimationFrame(()=>scrollSection(currentSection()));
})();
